        type: "p",
        text: "Poster le lien Steam partout ressemble à du progrès. En pratique, ça tue souvent l’engagement. Les communautés ne sont pas conçues pour réagir à des liens bruts. Sans contexte, récit ou pertinence, le lien est ignoré.",
