        text: "Beaucoup d’équipes repoussent les efforts wishlists jusqu’à se sentir proches du lancement. À ce moment-là, il n’y a plus de marge d’itération. Le message n’a pas été testé. Les visuels n’ont pas été validés. Les canaux n’ont pas été prouvés.",
