        type: "p",
        text: "Pour beaucoup de jeux indés PC, quelques milliers de wishlists avant le launch signalent un baseline d’intérêt sain. Des genres plus larges ou des prix plus élevés demandent souvent plus. Des niches plus petites peuvent réussir avec moins si l’engagement est profond.",
