        type: "p",
        text: "La plupart des développeurs indés qui travaillent sur des jeux PC et Steam n’ignorent pas le marketing. Ils le font activement. Les pages Steam sont en ligne. Les réseaux sociaux existent. Des festivals sont rejoints. Des démos sont préparées. Des mises à jour sont publiées.",
